def transform(grid):
    n, m = len(grid), len(grid[0])
    bg = grid[0][0]
    result = [row[:] for row in grid]
    red = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == 2]

    # Find the 4-connected red objects (points or axes).
    red_objects = []
    unused = set(red)
    while unused:
        stack = [unused.pop()]
        obj = []
        while stack:
            r, c = stack.pop()
            obj.append((r, c))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if p in unused:
                    unused.remove(p)
                    stack.append(p)
        red_objects.append(obj)

    for color in range(10):
        if color in (bg, 2):
            continue
        cells = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == color]
        if not cells:
            continue
        axis = min(red_objects, key=lambda obj: min(
            abs(r - ar) + abs(c - ac) for r, c in cells for ar, ac in obj))
        rows = [p[0] for p in axis]
        cols = [p[1] for p in axis]
        for r, c in cells:
            if len(axis) == 1:
                nr, nc = 2 * rows[0] - r, 2 * cols[0] - c
            elif min(rows) == max(rows):
                nr, nc = 2 * rows[0] - r, c
            else:
                nr, nc = r, 2 * cols[0] - c
            if 0 <= nr < n and 0 <= nc < m:
                result[nr][nc] = color
    return result
